-- @seq 787
CREATE VIEW public.acct_v_account_list WITH (security_invoker='true') AS
 SELECT a.tenant_id,
    a.entity_id,
    a.id AS account_id,
    a.code,
    a.name,
    a.account_type,
    a.subtype,
    a.detail_type,
    a.parent_account_id,
    a.is_active,
    a.is_posting_allowed,
    a.cash_flow_category,
    a.sort_order,
    ((
        CASE
            WHEN (a.normal_balance = 'debit'::text) THEN 1
            ELSE '-1'::integer
        END)::numeric * COALESCE(b.net, (0)::numeric)) AS balance,
    b.last_activity
   FROM (public.acct_chart_of_accounts a
     LEFT JOIN ( SELECT l.account_id,
            sum((l.debit - l.credit)) AS net,
            max(e.posting_date) AS last_activity
           FROM (public.acct_journal_lines l
             JOIN public.acct_journal_entries e ON ((e.id = l.journal_entry_id)))
          WHERE (e.status = ANY (ARRAY['posted'::text, 'reversed'::text]))
          GROUP BY l.account_id) b ON ((b.account_id = a.id)));

-- @seq 789
CREATE VIEW public.acct_v_ap_aging WITH (security_invoker='true') AS
 SELECT b.tenant_id,
    b.vendor_id,
    COALESCE(v.display_name, v.legal_name) AS vendor_name,
    sum(b.open_balance) FILTER (WHERE (COALESCE(b.due_date, b.bill_date) >= CURRENT_DATE)) AS current_due,
    sum(b.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 1) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 30))) AS days_1_30,
    sum(b.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 31) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 60))) AS days_31_60,
    sum(b.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 61) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 90))) AS days_61_90,
    sum(b.open_balance) FILTER (WHERE ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) > 90)) AS days_over_90,
    sum(b.open_balance) AS total_open
   FROM (public.acct_ap_bills b
     LEFT JOIN public.acct_vendors v ON ((v.id = b.vendor_id)))
  WHERE ((b.posted_journal_id IS NOT NULL) AND (b.status <> ALL (ARRAY['void'::text, 'draft'::text])) AND (b.open_balance > (0)::numeric))
  GROUP BY b.tenant_id, b.vendor_id, COALESCE(v.display_name, v.legal_name);

-- @seq 791
CREATE VIEW public.acct_v_ar_aging WITH (security_invoker='true') AS
 SELECT i.tenant_id,
    i.customer_id,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(concat_ws(' '::text, COALESCE(c.preferred_name, c.first_name), c.last_name), ''::text), c.email) AS customer_name,
    sum(i.open_balance) FILTER (WHERE (COALESCE(i.due_date, i.invoice_date) >= CURRENT_DATE)) AS current_due,
    sum(i.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) >= 1) AND ((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) <= 30))) AS days_1_30,
    sum(i.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) >= 31) AND ((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) <= 60))) AS days_31_60,
    sum(i.open_balance) FILTER (WHERE (((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) >= 61) AND ((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) <= 90))) AS days_61_90,
    sum(i.open_balance) FILTER (WHERE ((CURRENT_DATE - COALESCE(i.due_date, i.invoice_date)) > 90)) AS days_over_90,
    sum(i.open_balance) AS total_open
   FROM (public.acct_ar_invoices i
     LEFT JOIN public.crm_customers c ON ((c.id = i.customer_id)))
  WHERE ((i.posted_journal_id IS NOT NULL) AND (i.status <> ALL (ARRAY['void'::text, 'draft'::text, 'written_off'::text])) AND (i.open_balance > (0)::numeric))
  GROUP BY i.tenant_id, i.customer_id, COALESCE(NULLIF(c.company_name, ''::text), NULLIF(concat_ws(' '::text, COALESCE(c.preferred_name, c.first_name), c.last_name), ''::text), c.email);

-- @seq 792
CREATE VIEW public.acct_v_bank_feed_review WITH (security_invoker='true') AS
 SELECT t.tenant_id,
    t.id AS bank_transaction_id,
    t.bank_account_id,
    ba.name AS bank_account_name,
    t.transaction_date,
    t.description,
    t.payee,
    t.amount,
        CASE
            WHEN (t.amount < (0)::numeric) THEN (- t.amount)
            ELSE NULL::numeric
        END AS spent,
        CASE
            WHEN (t.amount > (0)::numeric) THEN t.amount
            ELSE NULL::numeric
        END AS received,
    t.review_status,
    t.suggested_rule_id,
    r.name AS suggested_rule_name,
    t.category_account_id,
    ((ca.code || ' '::text) || ca.name) AS category,
    t.payee_vendor_id,
    t.payee_customer_id,
    t.matched_doc_type,
    t.matched_doc_id
   FROM (((public.acct_bank_transactions t
     JOIN public.acct_bank_accounts ba ON ((ba.id = t.bank_account_id)))
     LEFT JOIN public.acct_bank_rules r ON ((r.id = t.suggested_rule_id)))
     LEFT JOIN public.acct_chart_of_accounts ca ON ((ca.id = t.category_account_id)))
  WHERE (t.review_status = ANY (ARRAY['for_review'::text, 'categorized'::text]));

-- @seq 793
CREATE VIEW public.acct_v_bank_feed_stages WITH (security_invoker='true') AS
 SELECT bt.tenant_id,
    bt.bank_account_id,
    ba.name AS bank_account,
    COALESCE(bt.review_stage, 'needs_review'::text) AS stage,
    count(*) AS items,
    sum(
        CASE
            WHEN (bt.amount > (0)::numeric) THEN bt.amount
            ELSE (0)::numeric
        END) AS money_in,
    sum(
        CASE
            WHEN (bt.amount < (0)::numeric) THEN (- bt.amount)
            ELSE (0)::numeric
        END) AS money_out,
    min(bt.transaction_date) AS oldest
   FROM (public.acct_bank_transactions bt
     JOIN public.acct_bank_accounts ba ON ((ba.id = bt.bank_account_id)))
  WHERE (bt.review_status = ANY (ARRAY['for_review'::text, 'categorized'::text]))
  GROUP BY bt.tenant_id, bt.bank_account_id, ba.name, COALESCE(bt.review_stage, 'needs_review'::text);

-- @seq 794
CREATE VIEW public.acct_v_bill_funnel WITH (security_invoker='true') AS
 SELECT b.tenant_id,
    st.stage,
    st.stage_order,
    count(*) AS bill_count,
    sum(
        CASE
            WHEN (st.stage = 'paid'::text) THEN b.total
            ELSE b.open_balance
        END) AS amount
   FROM (public.acct_ap_bills b
     CROSS JOIN LATERAL ( VALUES ('for_review'::text,1,((b.review_status = 'for_review'::text) AND (b.status = 'draft'::text))), ('pending_approval'::text,2,(b.approval_status = 'pending'::text)), ('unpaid'::text,3,((b.status = ANY (ARRAY['open'::text, 'partially_paid'::text])) AND (b.open_balance > (0)::numeric))), ('overdue'::text,4,((b.status = ANY (ARRAY['open'::text, 'partially_paid'::text])) AND (b.open_balance > (0)::numeric) AND (b.due_date < CURRENT_DATE))), ('payment_approval'::text,5,((b.payment_approval_status = 'pending'::text) AND (b.open_balance > (0)::numeric))), ('paid'::text,6,(b.status = 'paid'::text))) st(stage, stage_order, hit))
  WHERE st.hit
  GROUP BY b.tenant_id, st.stage, st.stage_order;

-- @seq 795
CREATE VIEW public.acct_v_monthly_pnl WITH (security_invoker='true') AS
 WITH m AS (
         SELECT e.tenant_id,
            e.entity_id,
            (date_trunc('month'::text, (e.posting_date)::timestamp with time zone))::date AS month,
            sum(
                CASE
                    WHEN (a.account_type = 'revenue'::text) THEN (l.credit - l.debit)
                    ELSE (0)::numeric
                END) AS income,
            sum(
                CASE
                    WHEN (a.account_type = 'expense'::text) THEN (l.debit - l.credit)
                    ELSE (0)::numeric
                END) AS spend
           FROM ((public.acct_journal_lines l
             JOIN public.acct_journal_entries e ON ((e.id = l.journal_entry_id)))
             JOIN public.acct_chart_of_accounts a ON ((a.id = l.account_id)))
          WHERE ((e.status = ANY (ARRAY['posted'::text, 'reversed'::text])) AND (NOT COALESCE(e.is_closing, false)) AND (a.account_type = ANY (ARRAY['revenue'::text, 'expense'::text])))
          GROUP BY e.tenant_id, e.entity_id, ((date_trunc('month'::text, (e.posting_date)::timestamp with time zone))::date)
        )
 SELECT m.tenant_id,
    m.entity_id,
    m.month,
    m.income,
    m.spend,
    (m.income - m.spend) AS net_income,
    p.income AS prior_year_income,
    p.spend AS prior_year_spend,
    (p.income - p.spend) AS prior_year_net_income
   FROM (m
     LEFT JOIN m p ON (((p.tenant_id = m.tenant_id) AND (NOT (p.entity_id IS DISTINCT FROM m.entity_id)) AND (p.month = ((m.month - '1 year'::interval))::date))));

-- @seq 796
CREATE VIEW public.acct_v_sales_funnel WITH (security_invoker='true') AS
 SELECT tenant_id,
        CASE
            WHEN (status = ANY (ARRAY['draft'::text, 'pending'::text, 'scheduled'::text])) THEN 'draft'::text
            WHEN (status = 'deposited'::text) THEN 'deposited'::text
            WHEN (status = 'paid'::text) THEN 'paid'::text
            WHEN ((open_balance > (0)::numeric) AND (due_date < CURRENT_DATE)) THEN 'overdue'::text
            ELSE 'not_paid'::text
        END AS stage,
    invoice_date,
    (date_trunc('month'::text, (invoice_date)::timestamp with time zone))::date AS invoice_month,
    (EXTRACT(year FROM invoice_date))::integer AS invoice_year,
    count(*) AS invoice_count,
    sum(total) AS total_amount,
    sum(open_balance) AS open_amount
   FROM public.acct_ar_invoices i
  WHERE (status <> ALL (ARRAY['void'::text, 'written_off'::text]))
  GROUP BY tenant_id,
        CASE
            WHEN (status = ANY (ARRAY['draft'::text, 'pending'::text, 'scheduled'::text])) THEN 'draft'::text
            WHEN (status = 'deposited'::text) THEN 'deposited'::text
            WHEN (status = 'paid'::text) THEN 'paid'::text
            WHEN ((open_balance > (0)::numeric) AND (due_date < CURRENT_DATE)) THEN 'overdue'::text
            ELSE 'not_paid'::text
        END, invoice_date, ((date_trunc('month'::text, (invoice_date)::timestamp with time zone))::date), ((EXTRACT(year FROM invoice_date))::integer);

-- @seq 797
CREATE VIEW public.acct_v_spend_by_category WITH (security_invoker='true') AS
 SELECT e.tenant_id,
    (date_trunc('month'::text, (e.posting_date)::timestamp with time zone))::date AS month,
    a.id AS account_id,
    a.code,
    a.name,
    sum((l.debit - l.credit)) AS amount
   FROM ((public.acct_journal_lines l
     JOIN public.acct_journal_entries e ON ((e.id = l.journal_entry_id)))
     JOIN public.acct_chart_of_accounts a ON ((a.id = l.account_id)))
  WHERE ((e.status = ANY (ARRAY['posted'::text, 'reversed'::text])) AND (NOT COALESCE(e.is_closing, false)) AND (a.account_type = 'expense'::text))
  GROUP BY e.tenant_id, ((date_trunc('month'::text, (e.posting_date)::timestamp with time zone))::date), a.id, a.code, a.name;

-- @seq 798
CREATE VIEW public.acct_v_tasks_due WITH (security_invoker='true') AS
 SELECT t.tenant_id,
    t.id AS task_id,
    t.close_id,
    c.period_end,
    t.section,
    t.title,
    t.status,
    t.assignee_id,
    t.reviewer_id,
    t.due_date,
    t.priority,
    t.tags,
    (t.due_date < CURRENT_DATE) AS overdue,
    (t.due_date - CURRENT_DATE) AS days_left,
    t.check_result
   FROM (public.acct_close_tasks t
     LEFT JOIN public.acct_closes c ON ((c.id = t.close_id)))
  WHERE (t.status <> ALL (ARRAY['done'::text, 'skipped'::text]));

-- @seq 799
CREATE VIEW public.acct_v_undeposited_payments WITH (security_invoker='true') AS
 SELECT r.tenant_id,
    r.id AS receipt_id,
    r.receipt_number,
    r.receipt_date,
    r.customer_id,
    r.amount,
    r.payment_method,
    r.reference
   FROM (public.acct_ar_receipts r
     JOIN public.acct_bank_accounts ba ON ((ba.id = r.deposit_account_id)))
  WHERE ((r.deposit_id IS NULL) AND (r.status = 'posted'::text) AND (COALESCE(r.payment_method, ''::text) <> 'gift_card'::text) AND (ba.account_kind = 'undeposited_funds'::text));

